// @ts-check
import { defineConfig } from 'astro/config';
import vue from '@astrojs/vue';
import tailwindcss from '@tailwindcss/vite';
import { readdirSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import site from './content/site.json' with { type: 'json' };

/**
 * MD Thermochrome is licensed and git-ignored (src/fonts/README.md). If its files are in
 * src/fonts/licensed/, generate @font-face rules for them; global.css imports the result.
 * Without them, the generated file is just a comment and the site uses IBM Plex Mono.
 */
function licensedFonts() {
  return {
    name: 'licensed-fonts',
    hooks: {
      'astro:config:setup': () => {
        const dir = fileURLToPath(new URL('./src/fonts/licensed/', import.meta.url));
        const weight = (n) => (/semi|smb/i.test(n) ? 600 : /bold|bd/i.test(n) ? 700 : /medium|med/i.test(n) ? 500 : 400);
        const rules = readdirSync(dir)
          .filter((f) => /thermochrome.*\.woff2?$/i.test(f))
          .sort()
          .map(
            (f) =>
              `@font-face { font-family: "MD Thermochrome"; src: url("./${f}") format("${f.endsWith('2') ? 'woff2' : 'woff'}"); ` +
              `font-weight: ${weight(f)}; font-style: ${/italic/i.test(f) ? 'italic' : 'normal'}; font-display: swap; }`
          );
        writeFileSync(
          `${dir}fonts.generated.css`,
          `/* Generated by astro.config.mjs from the files in this folder. Do not edit. */\n${rules.join('\n')}\n`
        );
      },
    },
  };
}

export default defineConfig({
  site: site.url,
  integrations: [vue(), licensedFonts()],
  build: {
    // External stylesheets only, so the CSP never has to allow inline styles.
    inlineStylesheets: 'never',
  },
  // Astro hashes every inline script/style it emits into a <meta> CSP. Directives a <meta>
  // can't carry (frame-ancestors) are sent as an HTTP header from public/_headers.
  security: {
    csp: {
      directives: [
        "default-src 'self'",
        "img-src 'self' data:",
        "font-src 'self'",
        "connect-src 'self'",
        "worker-src 'self'",
        "object-src 'none'",
        "base-uri 'self'",
        "form-action 'none'",
        'upgrade-insecure-requests',
      ],
    },
  },
  // No Markdown code blocks on this site; Shiki's inline styles would conflict with the CSP.
  markdown: { syntaxHighlight: false },
  devToolbar: { enabled: false },
  vite: {
    plugins: [tailwindcss()],
    // Never inline assets as data: URIs; fonts must load from 'self'.
    build: { assetsInlineLimit: 0 },
  },
});
